'use strict';
const {products:registry,cart,money,notify}=HlebnoShop;
const bread=registry.get('karavay-1');
if(document.body.dataset.shopPage==='catalog'){
 document.querySelector('#bread-list').innerHTML=[...registry.values()].filter(p=>p.variants).map(p=>`<article class="bread-card"><a href="${p.url}" class="bread-card-image"><img src="${p.image}" alt="Созданный визуал: ${p.name}"><span>ФИРМЕННЫЙ ХЛЕБ</span></a><div><p class="eyebrow">Живая закваска · ржаной</p><h2><a href="${p.url}">${p.name}</a></h2><p>${p.subtitle}</p><div class="bread-card-bottom"><span>500 г / 900 г<br><small>${p.variants.some(v=>Number.isFinite(v.price))?'от '+money(Math.min(...p.variants.filter(v=>Number.isFinite(v.price)).map(v=>v.price))):'Цена уточняется'}</small></span><a class="btn dark" href="${p.url}">Выбрать ${HlebnoIcons.svg('arrowRight')}</a></div></div></article>`).join('');
}
if(document.body.dataset.shopPage==='product'){
 let weight=bread.variants[0].id,slicing='whole',qty=1;
 const $=s=>document.querySelector(s);
 const feedback=HlebnoPurchaseFeedback.create({button:$('#product-add'),label:$('#purchase-label'),soundToggle:$('#purchase-sound'),soundStatus:$('#sound-status'),cartButton:$('.cart-open'),onSettled:()=>update()});
 function update(){const variant=bread.variants.find(v=>v.id===weight);if(!variant.slicingEnabled)slicing='whole';document.querySelectorAll('[data-weight]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.weight===weight)));document.querySelectorAll('[data-slicing]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.slicing===slicing));b.disabled=b.dataset.slicing==='sliced'&&!variant.slicingEnabled});$('#quantity').textContent=qty;$('#quantity-minus').disabled=qty<=1;$('#quantity-plus').disabled=qty>=99;$('#variant-price').textContent=Number.isFinite(variant.price)?money(variant.price):'Цена уточняется';$('#variant-stock').textContent=variant.available===false||variant.stock===0?'Нет в наличии':variant.available===true&&Number.isSafeInteger(variant.stock)?'В наличии: '+variant.stock+' шт.':'Наличие уточняется';const error=cart.reason(bread.id,weight,slicing,qty);$('#product-add').disabled=!!error||feedback.isBusy();$('#purchase-status').textContent=error?error+'. Заказ пока недоступен.':'Выбрано: '+variant.weight+' г · '+(slicing==='sliced'?'в нарезке':'без нарезки');$('#cutting-note').textContent=variant.slicingEnabled?'Нарезка доступна для выбранного веса.':'Нарезка для выбранного веса недоступна.';}
 for(const v of bread.variants){const b=document.createElement('button');b.className='option choice-card';b.type='button';b.dataset.weight=v.id;b.innerHTML=`<img class="choice-illustration " src="assets/choices/whole.webp" alt=""><span class="choice-copy"><strong>${v.weight} г</strong><small>${v.weight===500?'Малый каравай':'Большой каравай'}</small></span><span class="choice-check" aria-hidden="true">${HlebnoIcons.svg('check')}</span>`;b.addEventListener('click',()=>{feedback.reset();weight=v.id;qty=1;update()});$('#weight-options').append(b)}
 document.querySelectorAll('[data-slicing]').forEach(b=>b.addEventListener('click',()=>{feedback.reset();slicing=b.dataset.slicing;update()}));$('#quantity-minus').addEventListener('click',()=>{feedback.reset();qty=Math.max(1,qty-1);update()});$('#quantity-plus').addEventListener('click',()=>{feedback.reset();qty=Math.min(99,qty+1);update()});$('#product-add').addEventListener('click',()=>{if(feedback.isBusy()||$('#product-add').disabled)return;const result=cart.add(bread.id,weight,slicing,qty);notify(result.ok?'Каравай добавлен в корзину':result.error);update();if(result.ok)feedback.success()});window.addEventListener('hlebno-cart-change',update);
 function gallery(index){const item=bread.gallery[index];$('#gallery-photo').hidden=!item.src;$('#gallery-placeholder').hidden=!!item.src;if(item.src){$('#gallery-photo').src=item.src;$('#gallery-photo').alt='Созданный визуал «Каравай № 1»: '+item.label}$('#gallery-note').textContent=item.note;document.querySelectorAll('[data-gallery]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.gallery===index)));}
 bread.gallery.forEach((item,index)=>{const b=document.createElement('button');b.className='gallery-thumb';b.dataset.gallery=index;b.innerHTML=item.src?`<img src="${item.src}" alt=""><span>${item.label}</span>`:`<span class="thumb-placeholder">${HlebnoIcons.svg('plus')}</span><span>${item.label}</span>`;b.addEventListener('click',()=>gallery(index));$('#gallery-thumbs').append(b)});gallery(0);
 $('#description-copy').replaceChildren(...bread.description.map(t=>{const p=document.createElement('p');p.textContent=t;return p}));$('#storage-copy').textContent=bread.storage;
 $('#nutrition-rows').innerHTML=bread.nutrition.map(([name,unit])=>`<tr><th scope="row">${name}</th><td>— <span>${unit}</span></td></tr>`).join('');
 const tabs=[...document.querySelectorAll('[role="tab"]')];function chooseTab(tab){tabs.forEach(t=>{const on=t===tab;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!on})}tabs.forEach((t,i)=>{t.addEventListener('click',()=>chooseTab(t));t.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;else if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();chooseTab(tabs[n]);tabs[n].focus()})});update();
}
